-- Kit library: variants (GK 1 / GK 2, track jacket, V2 …), a picture per kit
-- with its credit, and BSC Young Boys' kits from 1898 to 2026/27.
-- The YB pictures and list come from Football Kit Archive (credited on every
-- kit, source = 'import'); used at Mohamed's decision while a licence is
-- requested. To remove them: delete from kits where image_credit = 'Football Kit Archive';
alter table public.kits
  add column if not exists variant text not null default '' check (char_length(variant) <= 40),
  add column if not exists image_path text check (image_path ~ '^/library/[a-z0-9/_.-]+\.(webp|png|jpg)$'),
  add column if not exists image_credit text check (char_length(image_credit) <= 80),
  add column if not exists image_credit_url text check (image_credit_url ~ '^https://');

drop index if exists public.kits_one_per_slot;
create unique index kits_one_per_slot on public.kits (club_id, season, kind, variant) where status = 'approved';

create or replace function public.admin_import_kits(p_kits jsonb)
returns int language plpgsql security definer set search_path = '' as $$
declare k jsonb; n int := 0; v_season text;
begin
  if not public.is_admin() then raise exception 'not authorized' using errcode = '42501'; end if;
  if jsonb_typeof(p_kits) <> 'array' or jsonb_array_length(p_kits) > 2000 then raise exception 'expected an array of at most 2000 kits' using errcode = '22023'; end if;
  for k in select * from jsonb_array_elements(p_kits) loop
    v_season := trim(k ->> 'season');
    insert into public.kits (club_id, season, season_year, kind, variant, brand, sponsor, pattern, colors, note, image_path, image_credit, image_credit_url, source, status)
    values (k ->> 'club', v_season, left(v_season, 4)::int, k ->> 'kind', coalesce(trim(k ->> 'variant'), ''), nullif(trim(k ->> 'brand'), ''), nullif(trim(k ->> 'sponsor'), ''),
            coalesce(k ->> 'pattern', 'plain'), array(select jsonb_array_elements_text(k -> 'colors')), nullif(trim(k ->> 'note'), ''),
            nullif(k ->> 'image', ''), nullif(k ->> 'credit', ''), nullif(k ->> 'credit_url', ''), 'import', 'approved')
    on conflict (club_id, season, kind, variant) where status = 'approved' do update
      set brand = coalesce(excluded.brand, kits.brand), sponsor = coalesce(excluded.sponsor, kits.sponsor), pattern = excluded.pattern, colors = excluded.colors,
          note = coalesce(excluded.note, kits.note), image_path = coalesce(excluded.image_path, kits.image_path),
          image_credit = coalesce(excluded.image_credit, kits.image_credit), image_credit_url = coalesce(excluded.image_credit_url, kits.image_credit_url);
    n := n + 1;
  end loop;
  return n;
end $$;

